def choose_move(observation):
    x = observation.get('self_position', {}).get('x', 0)
    y = observation.get('self_position', {}).get('y', 0)
    gw = observation.get('grid_width', 0)
    gh = observation.get('grid_height', 0)

    def clamp(v, a, b):
        return max(a, min(b, v))

    # default stay
    best = (0, 0)
    best_score = -10**9

    # helper: distance
    def dist(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    # If there is a resource, move toward closest
    resources = observation.get('resources', [])
    if isinstance(resources, list) and resources:
        rx = ry = None
        db = float('inf')
        for r in resources:
            if 'x' in r and 'y' in r:
                d = dist(x, y, r['x'], r['y'])
                if d < db:
                    db = d
                    rx, ry = r['x'], r['y']
        if rx is not None:
            dx = 0 if rx == x else (1 if rx > x else -1)
            dy = 0 if ry == y else (1 if ry > y else -1)
            best = (dx, dy)
            best_score = -db

    # Avoid obstacles by small detour if needed
    obstacles = observation.get('obstacles', [])
    if obstacles and best == (0, 0):
        # try all 4 dirs
        for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < gw and 0 <= ny < gh:
                blocked = False
                for o in obstacles:
                    ox = o.get('x')
                    oy = o.get('y')
                    if ox == nx and oy == ny:
                        blocked = True
                        break
                if not blocked:
                    best = (dx, dy)
                    break

    # If opponent is near, try to move away slightly
    opps = observation.get('opponents', [])
    if isinstance(opps, list) and opps:
        for o in opps:
            ox = o.get('x'); oy = o.get('y')
            if ox is None or oy is None:
                continue
            if dist(x, y, ox, oy) <= 2:
                # move away from this opponent
                dx = 0
                dy = 0
                if ox > x: dx = -1
                if ox < x: dx = 1
                if oy > y: dy = -1
                if oy < y: dy = 1
                nx, ny = x + dx, y + dy
                if 0 <= nx < gw and 0 <= ny < gh:
                    best = (dx, dy)
                    break

    return [best[0], best[1]]
